// Serialized into the Dashboard component; press appearance never changes device state.
function attachButtonPress ({ node, canPress }) {
  let pointer = null
  const keys = new Set(), listeners = []
  function listen (target, name, callback) {
    target.addEventListener(name, callback)
    listeners.push(() => target.removeEventListener(name, callback))
  }
  function render () {
    if (pointer !== null || keys.size) node.setAttribute('data-cpv-press', 'true')
    else node.removeAttribute('data-cpv-press')
  }
  function release () { pointer = null; keys.clear(); render() }
  function allowed () { return node.isConnected && !node.disabled && !document.hidden && canPress() }
  listen(node, 'pointerdown', event => {
    if (event.button !== 0 || pointer !== null || !allowed()) return
    pointer = event.pointerId
    render()
  })
  const pointerEnd = event => {
    if (pointer !== event.pointerId) return
    pointer = null
    render()
  }
  listen(window, 'pointerup', pointerEnd)
  listen(window, 'pointercancel', pointerEnd)
  listen(node, 'lostpointercapture', pointerEnd)
  listen(node, 'keydown', event => {
    if (![' ', 'Enter'].includes(event.key) || !allowed()) return
    keys.add(event.key)
    render()
  })
  listen(window, 'keyup', event => { if (keys.delete(event.key)) render() })
  listen(node, 'blur', release)
  listen(window, 'blur', release)
  listen(window, 'offline', release)
  listen(window, 'pagehide', release)
  listen(document, 'visibilitychange', () => { if (document.hidden) release() })
  return {
    release,
    check () { if (!allowed()) release() },
    dispose () { release(); for (const remove of listeners) remove() }
  }
}

module.exports = { attachButtonPress }
